def _party_minigame_raw_scenarios(mode: int) -> list[dict[str, Any]]:
    if mode not in (0, 1):
        _fail(f"PARTY_MINIGAME_MODE_INVALID:{mode}")
    return [
        {"mode": mode, "eligible": False, "selected_slot": None},
        *(
            {"mode": mode, "eligible": True, "selected_slot": slot}
            for slot in (*range(PARTY_MINIGAME_PARTY_COUNT),
                         PARTY_MINIGAME_CANCEL_SLOT)
        ),
    ]


def _party_minigame_control_owner(mode: int) -> str:
    if mode not in (0, 1):
        _fail(f"PARTY_MINIGAME_MODE_INVALID:{mode}")
    # _static_control_domains intentionally derives IDs from the hexadecimal
    # suffix.  Keep eight digits so mode 0 never falls back to an owner hash.
    return f"WIRELESS_MINIGAME_MODE:0x{mode:08X}"


def _party_minigame_input_control(mode: int) -> dict[str, Any]:
    return {
        "kind": PARTY_MINIGAME_KIND,
        "owner": _party_minigame_control_owner(mode),
        "candidate_values": _party_minigame_raw_scenarios(mode),
        "relation": PARTY_MINIGAME_RELATION,
    }


# TryBecomeLinkLeader/TryJoinLinkGroup consume one physical RFU session.  A
# retry result (8) is followed by exactly one completed result at the same
# role site; role and activity mode are correlated in a single 20-scenario
# owner so leader/join controls can never form a Cartesian product.
RFU_SESSION_KIND = "RFU_SESSION"
RFU_SESSION_CONTROL_ID = 0
RFU_SESSION_OWNER = "RFU_SESSION:0x00000000"
RFU_SESSION_RELATION = "NATURAL_RFU_ROLE_RESULT_SEQUENCE"
RFU_ROLE_RESULT_SEQUENCES: Mapping[int, tuple[tuple[int, ...], ...]] = {
    363: ((1,), (5,), (8, 1), (8, 5)),
    364: ((1,), (5,), (6,), (8, 1), (8, 5), (8, 6)),
}


def _build_rfu_session_scenarios() -> dict[str, dict[str, Any]]:
    result: dict[str, dict[str, Any]] = {}
    roles = {363: "leader", 364: "join"}
    suffixes = {
        (1,): "result1", (5,): "result5", (6,): "result6",
        (8, 1): "retry-result1", (8, 5): "retry-result5",
        (8, 6): "retry-result6",
    }
    for special_id, sequences in RFU_ROLE_RESULT_SEQUENCES.items():
        for mode in (0, 1):
            for sequence in sequences:
                scenario_id = (
                    f"mode{mode}-{roles[special_id]}-{suffixes[sequence]}"
                )
                result[scenario_id] = {
                    "scenario_id": scenario_id,
                    "special": special_id,
                    "endpoint_count": (
                        1 if sequence == (5,) else 2 if mode == 0 else 3
                    ),
                    "activity_mode": mode,
                    "result_sequence": list(sequence),
                    "fault_code": (
                        3 if sequence == (8, 6) else
                        2 if sequence[0] == 8 else
                        1 if sequence == (6,) else 0
                    ),
                }
    if len(result) != 20:
        raise AssertionError("RFU session scenario cardinality drift")
    return result


RFU_SESSION_SCENARIOS = _build_rfu_session_scenarios()


def _rfu_session_scenario_ids(special_id: int) -> tuple[str, ...]:
    if special_id not in RFU_ROLE_RESULT_SEQUENCES:
        _fail(f"RFU_SESSION_SPECIAL_INVALID:{special_id}")
    return tuple(
        scenario_id for scenario_id, payload in RFU_SESSION_SCENARIOS.items()
        if payload["special"] == special_id
    )


def _rfu_session_input_control(special_id: int) -> dict[str, Any]:
    return {
        "kind": RFU_SESSION_KIND,
        "owner": RFU_SESSION_OWNER,
        "candidate_values": list(_rfu_session_scenario_ids(special_id)),
        "relation": RFU_SESSION_RELATION,
    }


# The same asynchronous role specials are also used by the ordinary Pokemon
# Center wireless attendant.  That script never writes VAR_8005: its exact
# activity selector is VAR_8004 and covers five different link groups.  Keep
# this domain separate from the 20-case Joyful Game Corner RFU sweep so a
# missing mode writer can never be fabricated and the minigame exact-set
# remains stable.
CENTER_LINK_SESSION_KIND = "CENTER_LINK_SESSION"
CENTER_LINK_SESSION_CONTROL_ID = 0
CENTER_LINK_SESSION_OWNER = "CENTER_LINK_SESSION:0x00000000"
CENTER_LINK_SESSION_RELATION = \
    "NATURAL_CENTER_LINK_GROUP_ROLE_RESULT_SEQUENCE"
CENTER_LINK_GROUP_CAPACITIES: Mapping[int, tuple[int, int]] = {
    0: (2, 2),  # single battle
    1: (2, 2),  # double battle
    2: (4, 4),  # multi battle
    3: (2, 2),  # trade
    5: (2, 5),  # berry crush
}
CENTER_LINK_GROUP_ENDPOINT_COUNTS: Mapping[int, int] = {
    link_group: capacity_min
    for link_group, (capacity_min, _capacity_max)
    in CENTER_LINK_GROUP_CAPACITIES.items()
}
CENTER_LINK_GROUP_NAMES: Mapping[int, str] = {
    0: "single-battle",
    1: "double-battle",
    2: "multi-battle",
    3: "trade",
    5: "berry-crush",
}


def _build_center_link_session_scenarios() -> dict[str, dict[str, Any]]:
    result: dict[str, dict[str, Any]] = {}
    roles = {363: "leader", 364: "join"}
    suffixes = {
        (1,): "result1", (5,): "result5", (6,): "result6",
        (8, 1): "retry-result1", (8, 5): "retry-result5",
        (8, 6): "retry-result6",
    }
    for special_id, sequences in RFU_ROLE_RESULT_SEQUENCES.items():
        for link_group, (capacity_min, capacity_max) in sorted(
            CENTER_LINK_GROUP_CAPACITIES.items()
        ):
            for sequence in sequences:
                scenario_id = (
                    f"group{link_group}-{roles[special_id]}-"
                    f"{suffixes[sequence]}"
                )
                result[scenario_id] = {
                    "scenario_id": scenario_id,
                    "special": special_id,
                    "link_group": link_group,
                    "activity": CENTER_LINK_GROUP_NAMES[link_group],
                    "capacity_min": capacity_min,
                    "capacity_max": capacity_max,
                    "topology_policy": (
                        "LOCAL_CANCEL_BEFORE_DISCOVERY"
                        if sequence == (5,) else
                        "EXACT_SOURCE_CAPACITY"
                        if capacity_min == capacity_max else
                        "MINIMUM_SOURCE_VALID_REPRESENTATIVE"
                    ),
                    "endpoint_count": (
                        1 if sequence == (5,) else capacity_min
                    ),
                    "result_sequence": list(sequence),
                    "fault_code": (
                        3 if sequence == (8, 6) else
                        2 if sequence[0] == 8 else
                        1 if sequence == (6,) else 0
                    ),
                }
    if len(result) != 50:
        raise AssertionError("center link session scenario cardinality drift")
    return result


CENTER_LINK_SESSION_SCENARIOS = _build_center_link_session_scenarios()


def _center_link_session_scenario_ids(
    special_id: int,
) -> tuple[str, ...]:
    if special_id not in RFU_ROLE_RESULT_SEQUENCES:
        _fail(f"CENTER_LINK_SESSION_SPECIAL_INVALID:{special_id}")
    return tuple(
        scenario_id
        for scenario_id, payload in CENTER_LINK_SESSION_SCENARIOS.items()
        if payload["special"] == special_id
    )


def _center_link_session_input_control(special_id: int) -> dict[str, Any]:
    return {
        "kind": CENTER_LINK_SESSION_KIND,
        "owner": CENTER_LINK_SESSION_OWNER,
        "candidate_values": list(
            _center_link_session_scenario_ids(special_id)
        ),
        "relation": CENTER_LINK_SESSION_RELATION,
    }


def _link_role_input_controls(special_id: int) -> list[dict[str, Any]]:
    return [
        _rfu_session_input_control(special_id),
        _center_link_session_input_control(special_id),
    ]


