def _facility_scenario_keys(root: int) -> tuple[str, ...]:
    if root == FACILITY_MIRAGE_ROOT:
        families = ("mirage",)
    elif root == FACILITY_SHARED_ROOT:
        families = ("factory", "codex")
    else:
        _fail(f"FACILITY_SESSION_ROOT_INVALID:0x{root:08X}")
    return tuple(
        f"{family}/{scenario_id}"
        for family in families
        for scenario_id in FACILITY_SCENARIO_REGISTRIES[family]
    )


def _facility_input_control(root: int) -> dict[str, Any]:
    return {
        "kind": FACILITY_SESSION_KIND,
        "owner": FACILITY_SESSION_OWNERS[root],
        "candidate_values": sorted(
            _facility_scenario_keys(root), key=_stable,
        ),
        "relation": FACILITY_SESSION_RELATION,
    }


