def _is_engine_special_flag(identifier: int) -> bool:
    return ENGINE_SPECIAL_FLAG_START <= identifier <= ENGINE_SPECIAL_FLAG_END


def validate_engine_special_flag_owner_literal(
    project_source_rom: bytes,
    final_rom: bytes,
) -> dict[str, Any]:
    """``GetFlagAddr`` のfinal-ROM owner literalをbyte exactに固定する。

    upstream sourceは0x4000..0x407Fの意味を証明できるが、日本語版Vega実行
    ROMのlink済みaddressは証明できない。exact Stage60入力と生成final ROMの
    両方が同じ4-byte literalを保持する場合だけmGBA fixture/control ABIへ渡す。
    """

    if not isinstance(project_source_rom, bytes) \
            or not isinstance(final_rom, bytes):
        _fail("engine special flag owner literal ROM入力はbytes必須")
    offset = ENGINE_SPECIAL_FLAG_OWNER_LITERAL_ADDRESS - ROM_BASE
    expected = ENGINE_SPECIAL_FLAG_OWNER_LITERAL_RAW
    bindings: dict[str, dict[str, Any]] = {}
    for label, rom in (
        ("stage60_input", project_source_rom),
        ("final_rom", final_rom),
    ):
        if offset < 0 or offset + len(expected) > len(rom):
            _fail(f"engine special flag {label} owner literal範囲外")
        actual = rom[offset:offset + len(expected)]
        if actual != expected:
            _fail(
                "engine special flag GetFlagAddr owner literal drift:"
                f"{label}:address=0x{ENGINE_SPECIAL_FLAG_OWNER_LITERAL_ADDRESS:08X}:"
                f"expected={expected.hex()}:actual={actual.hex()}"
            )
        bindings[label] = {
            "rom_sha256": _sha(rom),
            "rom_size": len(rom),
            "literal_raw_hex": actual.hex(),
            "literal_sha256": _sha(actual),
        }
    if bindings["stage60_input"]["rom_sha256"] != STAGE60_SOURCE_SHA256:
        _fail("engine special flag owner literal Stage60 input SHA-256不一致")
    contract = {
        "schema_version": 1,
        "kind": "FINAL_JAPANESE_VEGA_GET_FLAG_ADDR_OWNER_LITERAL",
        "status": "PASS",
        "function": "GetFlagAddr",
        "literal_address":
            f"0x{ENGINE_SPECIAL_FLAG_OWNER_LITERAL_ADDRESS:08X}",
        "literal_value": f"0x{ENGINE_SPECIAL_FLAG_OWNER_ADDRESS:08X}",
        "literal_raw_hex": expected.hex(),
        "literal_sha256": _sha(expected),
        "owner": {
            "name": "sSpecialFlags",
            "address": f"0x{ENGINE_SPECIAL_FLAG_OWNER_ADDRESS:08X}",
            "size": ENGINE_SPECIAL_FLAG_OWNER_SIZE,
            "id_range": [ENGINE_SPECIAL_FLAG_START, ENGINE_SPECIAL_FLAG_END],
            "encoding": "PLAIN_BITSET_ID_0x4000_IS_BIT_0",
            "persistence": "EWRAM_VOLATILE_NOT_SAVEBLOCK",
        },
        "bindings": bindings,
        "relation": (
            "GET_FLAG_ADDR_LITERAL_IS_RUNTIME_OWNER;"
            "UPSTREAM_SYMBOL_ADDRESS_GUESS_FORBIDDEN"
        ),
        "assertions": {
            "stage60_input_literal_exact": True,
            "final_rom_literal_exact": True,
            "stage60_input_sha256_exact": True,
            "owner_is_ewram_16_byte_bitset": True,
        },
    }
    return contract

