def _validate_change_pokemon_nickname_no_result(
    stage61_rom: bytes,
    entry: Mapping[str, Any],
    source_blobs: Mapping[str, bytes] | None,
) -> None:
    """SPECIAL158のasync naming handoffがVAR_RESULT非writerであると固定する。"""

    source = entry.get("source")
    binding = entry.get("rom_binding")
    result_contract = entry.get("result_contract")
    expected_source = {
        "path": _SPECIAL158_NO_RESULT_SOURCE["path"],
        "definition_line": _SPECIAL158_NO_RESULT_SOURCE["entry_line"],
        "sha256": _SPECIAL158_NO_RESULT_SOURCE["sha256"],
    }
    if entry.get("symbol") != "ChangePokemonNickname" \
            or entry.get("execution") != "ASYNC_CONTEXT2" \
            or source != expected_source \
            or binding != _SPECIAL158_NO_RESULT_ROM_BINDING \
            or result_contract != {
                "global_var_result_write": None,
                "specialvar_return": None,
            }:
        _fail("SPECIAL158_NO_RESULT_ABI_DRIFT")
    if _sha(_read(
        stage61_rom, 0x080CD200, 0xBC,
        "SPECIAL158 ChangePokemonNickname full span",
    )) != _SPECIAL158_NO_RESULT_ROM_BINDING["sha256"]:
        _fail("SPECIAL158_NO_RESULT_ROM_DRIFT")
    if source_blobs is None:
        return
    path = str(_SPECIAL158_NO_RESULT_SOURCE["path"])
    blob = source_blobs.get(path)
    if not isinstance(blob, bytes) \
            or _sha(blob) != _SPECIAL158_NO_RESULT_SOURCE["sha256"]:
        _fail("SPECIAL158_NO_RESULT_SOURCE_DRIFT")
    if _definition_line_in_blob(blob, "ChangePokemonNickname") != 1651 \
            or _definition_line_in_blob(
                blob, "ChangePokemonNickname_CB",
            ) != 1665:
        _fail("SPECIAL158_NO_RESULT_SOURCE_DEFINITION_DRIFT")
    lines = blob.decode("utf-8", errors="strict").splitlines()
    first = int(_SPECIAL158_NO_RESULT_SOURCE["body_first_line"])
    last = int(_SPECIAL158_NO_RESULT_SOURCE["body_last_line"])
    if last > len(lines) \
            or lines[1651 - 1].strip() != \
                "void ChangePokemonNickname(void)" \
            or lines[1662 - 1].strip() != \
                _SPECIAL158_NO_RESULT_SOURCE["handoff_source"] \
            or lines[1665 - 1].strip() != \
                "static void ChangePokemonNickname_CB(void)" \
            or lines[1668 - 1].strip() != \
                _SPECIAL158_NO_RESULT_SOURCE["completion_source"] \
            or "gSpecialVar_Result" in "\n".join(lines[first - 1:last]):
        _fail("SPECIAL158_NO_RESULT_SOURCE_BODY_DRIFT")

