def _special_global_result_writer_evidence(
    special_id: int,
    stage61_rom: bytes,
    source_blobs: Mapping[str, bytes] | None,
    *,
    clean_rom: bytes | None = None,
    stage60_rom: bytes | None = None,
) -> dict[str, Any] | None:
    """Return and independently verify the pinned result-writer graph."""

    raw_spec = _SPECIAL_GLOBAL_RESULT_WRITER_SPECS.get(special_id)
    if raw_spec is None:
        return None
    evidence = deepcopy(dict(raw_spec))
    functions = evidence["source_functions"]
    by_symbol = {row["symbol"]: row for row in functions}
    if len(by_symbol) != len(functions):
        _fail(f"SPECIAL{special_id} result writer symbol重複")
    for function in functions:
        path = function["path"]
        expected_sha = function["source_sha256"]
        if source_blobs is None:
            continue
        blob = source_blobs.get(path)
        if not isinstance(blob, bytes) or _sha(blob) != expected_sha:
            _fail(f"SPECIAL{special_id} result writer source不一致:{path}")
        if _definition_line_in_blob(blob, function["symbol"]) != \
                function["definition_line"]:
            _fail(
                f"SPECIAL{special_id} result writer definition不一致:"
                f"{function['symbol']}"
            )
        lines = blob.decode("utf-8", errors="strict").splitlines()
        for site in function["write_sites"] + function["control_sites"]:
            line = site["line"]
            if not 1 <= line <= len(lines) \
                    or lines[line - 1].strip() != site["source_line"]:
                _fail(
                    f"SPECIAL{special_id} result writer source line不一致:"
                    f"{path}:{line}"
                )
    for edge in evidence["ownership_edges"]:
        caller = by_symbol.get(edge["caller"])
        callee = by_symbol.get(edge["callee"])
        if caller is None or callee is None or caller["path"] != callee["path"]:
            _fail(f"SPECIAL{special_id} result writer ownership edge不正")
        if source_blobs is not None:
            lines = source_blobs[caller["path"]].decode(
                "utf-8", errors="strict",
            ).splitlines()
            line = edge["line"]
            if not 1 <= line <= len(lines) \
                    or lines[line - 1].strip() != edge["source_line"]:
                _fail(
                    f"SPECIAL{special_id} result ownership source line不一致:"
                    f"{caller['path']}:{line}"
                )
    for binding in evidence["additional_rom_bindings"]:
        address = _as_address(
            binding["address"], f"SPECIAL{special_id} result writer address",
        )
        length = binding["byte_length"]
        if isinstance(length, bool) or not isinstance(length, int) \
                or not 2 <= length <= 0x4000:
            _fail(f"SPECIAL{special_id} result writer span不正")
        expected_sha = _abi_sha(
            binding["sha256"], f"SPECIAL{special_id} result writer span",
        )
        final_span = _read(
            stage61_rom, address, length,
            f"SPECIAL{special_id} result writer final span",
        )
        if _sha(final_span) != expected_sha:
            _fail(
                f"SPECIAL{special_id} result writer ROM binding不一致:"
                f"{binding['symbol']}"
            )
        if clean_rom is None and stage60_rom is None:
            continue
        if clean_rom is None or stage60_rom is None:
            _fail(f"SPECIAL{special_id} result writer ROM provenance入力不足")
        stage60_span = _read(
            stage60_rom, address, length,
            f"SPECIAL{special_id} result writer Stage60 span",
        )
        if stage60_span != final_span:
            _fail(
                f"SPECIAL{special_id} result writer changed after Stage60:"
                f"{binding['symbol']}"
            )
        provenance = binding["provenance"]
        clean_span = _read(
            clean_rom, address, length,
            f"SPECIAL{special_id} result writer clean span",
        )
        if provenance == "CLEAN_STAGE60_STAGE61_FULL_SPAN":
            if clean_span != final_span:
                _fail(
                    f"SPECIAL{special_id} result writer clean span不一致:"
                    f"{binding['symbol']}"
                )
        elif provenance != "STAGE60_STAGE61_ADAPTED_STOCK_FULL_SPAN" \
                or clean_span == final_span:
            _fail(
                f"SPECIAL{special_id} result writer provenance不正:"
                f"{binding['symbol']}"
            )
    completed = sorted({
        value
        for function in functions
        for site in function["write_sites"]
        if site["phase"] != "NONTERMINAL_SENTINEL"
        for value in site["candidate_values"]
    })
    nonterminal = sorted({
        value
        for function in functions
        for site in function["write_sites"]
        if site["phase"] == "NONTERMINAL_SENTINEL"
        for value in site["candidate_values"]
    })
    if completed != evidence["completed_candidate_values"] \
            or nonterminal != evidence["nonterminal_candidate_values"]:
        _fail(f"SPECIAL{special_id} result writer candidate closure不一致")
    return evidence


