def _validate_native_result_enum_header(
    symbol: str,
    evidence: Mapping[str, Any],
    source_blobs: Mapping[str, bytes] | None,
) -> dict[str, int]:
    """Validate the exact enum declaration used by a native writer graph.

    Whenever source evidence is supplied, the header key, its full SHA, every
    enum row, and the pinned translation-unit include are all mandatory.
    ``source_blobs=None`` remains the explicit manifest-only validation mode;
    a partial source mapping cannot silently downgrade header verification.
    """

    header = evidence.get("result_enum_header")
    required = {
        "path", "source_sha256", "type_name", "start_line", "end_line",
        "translation_unit_include", "members",
    }
    if not isinstance(header, Mapping) or set(header) != required:
        _fail(f"{symbol} result enum header schema不正")
    path = header["path"]
    type_name = header["type_name"]
    start_line = header["start_line"]
    end_line = header["end_line"]
    if not isinstance(path, str) or not path.endswith(".h") \
            or not isinstance(type_name, str) \
            or re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", type_name) is None \
            or isinstance(start_line, bool) or not isinstance(start_line, int) \
            or isinstance(end_line, bool) or not isinstance(end_line, int) \
            or not 1 <= start_line < end_line:
        _fail(f"{symbol} result enum header identity不正")
    expected_sha = _abi_sha(
        header["source_sha256"], f"{symbol} result enum header",
    )

    include = header["translation_unit_include"]
    if not isinstance(include, Mapping) or set(include) != {
        "path", "line", "source_line",
    } or not isinstance(include["path"], str) \
            or isinstance(include["line"], bool) \
            or not isinstance(include["line"], int) \
            or include["line"] <= 0 \
            or include["source_line"] != f'#include "{path.rsplit("/", 1)[-1]}"':
        _fail(f"{symbol} result enum include binding不正")
    if source_blobs is not None:
        translation_unit = source_blobs.get(include["path"])
        if not isinstance(translation_unit, bytes):
            _fail(f"{symbol} result enum translation unit欠落")
        include_lines = translation_unit.decode(
            "utf-8", errors="strict",
        ).splitlines()
        if include["line"] > len(include_lines) or include_lines[
            include["line"] - 1
        ].strip() != include["source_line"]:
            _fail(f"{symbol} result enum include source line不一致")

    members = header["members"]
    if not isinstance(members, list) or not members:
        _fail(f"{symbol} result enum members不正")
    enum_values: dict[str, int] = {}
    member_lines: set[int] = set()
    for member in members:
        if not isinstance(member, Mapping) or set(member) != {
            "symbol", "value", "line",
        } or not isinstance(member["symbol"], str) \
                or re.fullmatch(
                    r"RESEARCH_RESULT_[A-Z0-9_]+", member["symbol"],
                ) is None \
                or isinstance(member["value"], bool) \
                or not isinstance(member["value"], int) \
                or not 0 <= member["value"] <= 0xFFFF \
                or isinstance(member["line"], bool) \
                or not isinstance(member["line"], int) \
                or not start_line < member["line"] < end_line \
                or member["symbol"] in enum_values \
                or member["line"] in member_lines:
            _fail(f"{symbol} result enum member schema不正")
        enum_values[member["symbol"]] = member["value"]
        member_lines.add(member["line"])
    if [member["line"] for member in members] != sorted(member_lines) \
            or len(set(enum_values.values())) != len(enum_values):
        _fail(f"{symbol} result enum member order/value重複")

    if source_blobs is not None:
        blob = source_blobs.get(path)
        if not isinstance(blob, bytes) or _sha(blob) != expected_sha:
            _fail(f"{symbol} result enum header source不一致:{path}")
        lines = blob.decode("utf-8", errors="strict").splitlines()
        if end_line > len(lines) \
                or lines[start_line - 1].strip() != \
                f"typedef enum {type_name} {{" \
                or lines[end_line - 1].strip() != f"}} {type_name};":
            _fail(f"{symbol} result enum declaration不一致")
        parsed: list[tuple[str, int, int]] = []
        member_pattern = re.compile(
            r"(RESEARCH_RESULT_[A-Z0-9_]+)\s*=\s*(0[xX][0-9A-Fa-f]+|[0-9]+)\s*,?"
        )
        for line_number in range(start_line + 1, end_line):
            source_line = lines[line_number - 1].strip()
            match = member_pattern.fullmatch(source_line)
            if match is None:
                _fail(
                    f"{symbol} result enum unparsed member:{line_number}"
                )
            parsed.append((match.group(1), int(match.group(2), 0), line_number))
        expected = [
            (member["symbol"], member["value"], member["line"])
            for member in members
        ]
        if parsed != expected:
            _fail(f"{symbol} result enum member mismatch")
    return enum_values


def _native_global_result_writer_evidence(
    symbol: str,
    stage61_rom: bytes,
    source_blobs: Mapping[str, bytes] | None,
    *,
    stage60_rom: bytes | None = None,
) -> dict[str, Any] | None:
    """Verify a source/ROM-bound, entry-reachable native writer graph."""

    raw_spec = _NATIVE_GLOBAL_RESULT_WRITER_SPECS.get(symbol)
    if raw_spec is None:
        return None
    evidence = deepcopy(dict(raw_spec))
    if set(evidence) != {
        "schema_version", "kind", "completed_candidate_values",
        "entry_rom_binding_function", "result_enum_header",
        "source_functions", "ownership_edges", "additional_rom_bindings",
    } or evidence["schema_version"] != 2 \
            or evidence["kind"] != \
            "NATIVE_GLOBAL_VAR_RESULT_WRITER_GRAPH_V2":
        _fail(f"{symbol} result writer graph schema不正")

    functions = evidence["source_functions"]
    if not isinstance(functions, list) or not functions:
        _fail(f"{symbol} result writer function集合不正")
    by_symbol: dict[str, Mapping[str, Any]] = {}
    source_lines: dict[str, list[str]] = {}
    for function in functions:
        if not isinstance(function, Mapping) or set(function) != {
            "path", "source_sha256", "symbol", "definition_line", "role",
            "rom_binding_owners", "result_sites", "control_sites",
        } or not isinstance(function["symbol"], str) \
                or not function["symbol"] \
                or function["symbol"] in by_symbol \
                or not isinstance(function["path"], str) \
                or not function["path"] \
                or isinstance(function["definition_line"], bool) \
                or not isinstance(function["definition_line"], int) \
                or function["definition_line"] <= 0 \
                or not isinstance(function["role"], str) \
                or not function["role"] \
                or not isinstance(function["rom_binding_owners"], list) \
                or not function["rom_binding_owners"] \
                or len(set(function["rom_binding_owners"])) != \
                len(function["rom_binding_owners"]) \
                or not all(isinstance(owner, str) and owner
                           for owner in function["rom_binding_owners"]) \
                or not isinstance(function["result_sites"], list) \
                or not isinstance(function["control_sites"], list):
            _fail(f"{symbol} result writer function schema不正")
        _abi_sha(
            function["source_sha256"],
            f"{symbol} result writer source:{function['symbol']}",
        )
        by_symbol[function["symbol"]] = function
        if source_blobs is not None:
            path = function["path"]
            blob = source_blobs.get(path)
            if not isinstance(blob, bytes) \
                    or _sha(blob) != function["source_sha256"]:
                _fail(f"{symbol} result writer source不一致:{path}")
            if _definition_line_in_blob(blob, function["symbol"]) != \
                    function["definition_line"]:
                _fail(
                    f"{symbol} result writer definition不一致:"
                    f"{function['symbol']}"
                )
            source_lines[path] = blob.decode(
                "utf-8", errors="strict",
            ).splitlines()

    entry_symbol = evidence["entry_rom_binding_function"]
    entry = by_symbol.get(entry_symbol)
    if entry is None or entry_symbol != symbol \
            or entry["role"] != "FIXED_CONFIRMED_ENTRY" \
            or entry["rom_binding_owners"] != [entry_symbol]:
        _fail(f"{symbol} result writer entry function不正")
    enum_values = _validate_native_result_enum_header(
        symbol, evidence, source_blobs,
    )

    # Validate every source site and independently derive direct enum values.
    derived_sites: list[tuple[Mapping[str, Any], Mapping[str, Any]]] = []
    for function in functions:
        lines = source_lines.get(function["path"])
        for site in function["result_sites"]:
            base_keys = {"line", "source_line", "candidate_values"}
            if not isinstance(site, Mapping) \
                    or set(site) not in (base_keys, base_keys | {
                        "candidate_source",
                    }) \
                    or isinstance(site["line"], bool) \
                    or not isinstance(site["line"], int) \
                    or site["line"] <= 0 \
                    or not isinstance(site["source_line"], str) \
                    or not site["source_line"] \
                    or not isinstance(site["candidate_values"], list) \
                    or not site["candidate_values"] \
                    or any(isinstance(value, bool) or not isinstance(value, int)
                           or not 0 <= value <= 0xFFFF
                           for value in site["candidate_values"]) \
                    or site["candidate_values"] != sorted(set(
                        site["candidate_values"]
                    )):
                _fail(f"{symbol} result writer result site schema不正")
            if lines is not None and (
                site["line"] > len(lines)
                or lines[site["line"] - 1].strip() != site["source_line"]
            ):
                _fail(
                    f"{symbol} result writer source line不一致:"
                    f"{site['line']}"
                )
            tokens = re.findall(
                r"\bRESEARCH_RESULT_[A-Z0-9_]+\b", site["source_line"],
            )
            if "candidate_source" in site:
                if tokens:
                    _fail(f"{symbol} derived result siteにdirect enum混在")
                derived_sites.append((function, site))
            else:
                if not tokens or any(token not in enum_values for token in tokens):
                    _fail(f"{symbol} result site enum参照不正")
                expected_values = sorted({enum_values[token] for token in tokens})
                if site["candidate_values"] != expected_values:
                    _fail(f"{symbol} result site enum value不一致")
        for site in function["control_sites"]:
            if not isinstance(site, Mapping) or set(site) != {
                "line", "source_line", "relation",
            } or isinstance(site["line"], bool) \
                    or not isinstance(site["line"], int) \
                    or site["line"] <= 0 \
                    or not isinstance(site["source_line"], str) \
                    or not site["source_line"] \
                    or not isinstance(site["relation"], str) \
                    or not site["relation"]:
                _fail(f"{symbol} result writer control site schema不正")
            if lines is not None and (
                site["line"] > len(lines)
                or lines[site["line"] - 1].strip() != site["source_line"]
            ):
                _fail(
                    f"{symbol} result writer source line不一致:"
                    f"{site['line']}"
                )

    edges = evidence["ownership_edges"]
    if not isinstance(edges, list) or not edges:
        _fail(f"{symbol} result writer ownership graph欠落")
    edge_keys: set[tuple[str, str, int]] = set()
    adjacency: dict[str, set[str]] = {name: set() for name in by_symbol}
    for edge in edges:
        if not isinstance(edge, Mapping) or set(edge) != {
            "caller", "callee", "line", "source_line", "fixed_arguments",
        } or not isinstance(edge["caller"], str) \
                or not isinstance(edge["callee"], str) \
                or isinstance(edge["line"], bool) \
                or not isinstance(edge["line"], int) or edge["line"] <= 0 \
                or not isinstance(edge["source_line"], str) \
                or not edge["source_line"] \
                or not isinstance(edge["fixed_arguments"], Mapping) \
                or any(not isinstance(name, str) or not name
                       or isinstance(value, bool) or not isinstance(value, int)
                       or not 0 <= value <= 0xFFFF
                       for name, value in edge["fixed_arguments"].items()):
            _fail(f"{symbol} result writer ownership edge schema不正")
        caller = by_symbol.get(edge["caller"])
        callee = by_symbol.get(edge["callee"])
        identity = (edge["caller"], edge["callee"], edge["line"])
        if caller is None or callee is None or caller["path"] != callee["path"] \
                or caller is callee or identity in edge_keys:
            _fail(f"{symbol} result writer ownership edge不正")
        edge_keys.add(identity)
        adjacency[edge["caller"]].add(edge["callee"])
        lines = source_lines.get(caller["path"])
        if lines is not None and (
            edge["line"] > len(lines)
            or lines[edge["line"] - 1].strip() != edge["source_line"]
        ):
            _fail(
                f"{symbol} result ownership source line不一致:"
                f"{edge['line']}"
            )

    reachable = {entry_symbol}
    pending = [entry_symbol]
    while pending:
        caller = pending.pop()
        for callee in adjacency[caller]:
            if callee not in reachable:
                reachable.add(callee)
                pending.append(callee)
    if reachable != set(by_symbol):
        _fail(
            f"{symbol} result writer reachable function closure不一致:"
            f"missing={sorted(set(by_symbol) - reachable)}"
        )

    sinks = [
        function for function in functions
        if function["role"] == "GLOBAL_VAR_RESULT_SINK"
    ]
    if len(sinks) != 1:
        _fail(f"{symbol} result writer sink cardinality不正")
    sink = sinks[0]
    sink_symbol = sink["symbol"]
    if sink["result_sites"] or adjacency[sink_symbol] \
            or sink["control_sites"] != [{
                "line": 540,
                "source_line": "*G_SPECIAL_RESULT = result;",
                "relation": "WRITE_DELEGATED_RESULT_EXACT",
            }]:
        _fail(f"{symbol} result writer sink contract不正")
    expected_sink_sites = {
        (function["symbol"], site["line"], site["source_line"])
        for function in functions
        for site in function["result_sites"]
        if re.fullmatch(
            r"return\s+set_result\s*\(.+\)\s*;", site["source_line"],
        ) is not None
    }
    actual_sink_sites = {
        (edge["caller"], edge["line"], edge["source_line"])
        for edge in edges if edge["callee"] == sink_symbol
    }
    if actual_sink_sites != expected_sink_sites:
        _fail(f"{symbol} result writer reachable sink closure不一致")

    # A callee which is inlined or outlined must be covered by every bound ROM
    # span that calls it.  This ties logical source reachability to the exact
    # entry and PurchaseByIndex bytes instead of accepting a source-only graph.
    bindings = evidence["additional_rom_bindings"]
    if not isinstance(bindings, list):
        _fail(f"{symbol} result writer ROM binding集合不正")
    binding_symbols = [binding.get("symbol") for binding in bindings
                       if isinstance(binding, Mapping)]
    if len(binding_symbols) != len(bindings) \
            or len(set(binding_symbols)) != len(binding_symbols) \
            or any(name not in by_symbol or name == entry_symbol
                   for name in binding_symbols):
        _fail(f"{symbol} result writer ROM binding owner不正")
    bound_symbols = {entry_symbol, *binding_symbols}
    for function in functions:
        owners = set(function["rom_binding_owners"])
        if not owners <= bound_symbols:
            _fail(f"{symbol} result writer source/ROM owner closure不一致")
    for edge in edges:
        if edge["callee"] == sink_symbol and not set(
            by_symbol[edge["caller"]]["rom_binding_owners"]
        ) <= set(sink["rom_binding_owners"]):
            _fail(f"{symbol} result writer sink ROM owner不一致")
    for binding in bindings:
        if set(binding) != {
            "symbol", "address", "byte_length", "sha256", "provenance",
        }:
            _fail(f"{symbol} result writer ROM binding schema不正")
        address = _as_address(binding["address"], f"{symbol} writer address")
        length = binding["byte_length"]
        if isinstance(length, bool) or not isinstance(length, int) \
                or not 2 <= length <= 0x4000:
            _fail(f"{symbol} result writer ROM binding span不正")
        final_span = _read(
            stage61_rom, address, length, f"{symbol} final writer span",
        )
        if _sha(final_span) != _abi_sha(
            binding["sha256"], f"{symbol} writer span",
        ):
            _fail(f"{symbol} result writer ROM binding不一致")
        if stage60_rom is not None and _read(
            stage60_rom, address, length, f"{symbol} Stage60 writer span",
        ) != final_span:
            _fail(f"{symbol} result writer changed after Stage60")
        if binding["provenance"] != "STAGE60_STAGE61_PROJECT_FULL_SPAN":
            _fail(f"{symbol} result writer provenance不正")

    for function, site in derived_sites:
        source = site["candidate_source"]
        if not isinstance(source, Mapping) or set(source) != {
            "symbol", "excluded_enum_members",
        } or not isinstance(source["symbol"], str) \
                or source["symbol"] not in by_symbol \
                or not isinstance(source["excluded_enum_members"], list) \
                or not source["excluded_enum_members"] \
                or len(set(source["excluded_enum_members"])) != \
                len(source["excluded_enum_members"]) \
                or any(name not in enum_values
                       for name in source["excluded_enum_members"]) \
                or source["symbol"] not in adjacency[function["symbol"]]:
            _fail(f"{symbol} derived result source不正")
        source_values = {
            value
            for source_site in by_symbol[source["symbol"]]["result_sites"]
            for value in source_site["candidate_values"]
        }
        excluded = {
            enum_values[name] for name in source["excluded_enum_members"]
        }
        if site["candidate_values"] != sorted(source_values - excluded):
            _fail(f"{symbol} derived result candidate closure不一致")

    # The one excluded source branch is controlled by confirmed=0, while the
    # only entry edge fixes confirmed=1.  Pin both halves so CANCELLED cannot be
    # reintroduced merely by broadening the enum/result union.
    entry_transaction_edges = [
        edge for edge in edges
        if edge["caller"] == entry_symbol
        and edge["callee"] == "ResearchEconomy_PurchaseByIndex"
    ]
    transaction = by_symbol.get("ResearchEconomy_PurchaseByIndex")
    if entry_transaction_edges != [{
        "caller": "ResearchEconomy_PurchaseSelected",
        "callee": "ResearchEconomy_PurchaseByIndex",
        "line": 1509,
        "source_line": (
            "return ResearchEconomy_PurchaseByIndex("
            "G_VOLATILE->selected_catalog, 1u);"
        ),
        "fixed_arguments": {"confirmed": 1},
    }] or transaction is None or transaction["control_sites"] != [{
        "line": 1212,
        "source_line": "if (!confirmed)",
        "relation": "CANCELLED_BRANCH_UNREACHABLE_FROM_FIXED_CONFIRMED_ONE",
    }]:
        _fail(f"{symbol} fixed confirmed reachability不正")

    candidates = sorted({
        value
        for function in functions
        for site in function["result_sites"]
        if (function["symbol"], site["line"], site["source_line"])
        in expected_sink_sites
        for value in site["candidate_values"]
    })
    completed = evidence["completed_candidate_values"]
    if not isinstance(completed, list) \
            or completed != sorted(set(completed)) \
            or any(value not in enum_values.values() for value in completed) \
            or candidates != completed \
            or enum_values["RESEARCH_RESULT_CANCELLED"] in completed:
        _fail(f"{symbol} result writer candidate closure不一致")
    return evidence


